#include <iostream>
#include <vector>
#include <queue>
#include <cstring>
#include <climits>
#include <cmath>
#include <complex>
#include <chrono>
#include <random>
#include <iomanip>
#include <cassert>

using namespace std;

typedef long long ll;
typedef long double ld;
typedef pair<int,int> pii;
typedef pair<ll,ll> pll;
typedef pair<ld,ld> pdd;
typedef complex<ld> pt;

const char NL = '\n';
const ll INF = 0x3f3f3f3f;
const ll INFLL = 0x3f3f3f3f3f3f3f3f;
const ll MOD = 1e9+7;
const ld EPS = 1e-10;
mt19937_64 rng(chrono::high_resolution_clock::now().time_since_epoch().count());

const int TOTAL_TIME = 99;
const int MAX_COST_LEVELS = 15;

struct MinCostFlow {
    static const int MAX_NODES = 50*TOTAL_TIME + 2;
    static const int MAX_EDGES = 2*MAX_NODES*MAX_COST_LEVELS + MAX_NODES + 7;

    int par[MAX_NODES], first[MAX_NODES], nxt[2*MAX_EDGES], ep[2*MAX_EDGES], edge_count;
    ll flo[2*MAX_EDGES], cap[2*MAX_EDGES], cost[2*MAX_EDGES];

    void initialize() {
        edge_count = 0;
        memset(first, -1, sizeof(first));
        memset(flo, 0, sizeof(flo));
    }

    void add_connection(int a, int b, ll capacity=1, ll price=0) {
        nxt[edge_count] = first[ep[edge_count] = a];
        first[ep[edge_count]] = edge_count;
        cap[edge_count] = capacity;
        cost[edge_count] = price;
        ++edge_count;

        nxt[edge_count] = first[ep[edge_count] = b];
        first[ep[edge_count]] = edge_count;
        cap[edge_count] = 0;
        cost[edge_count] = -price;
        ++edge_count;
    }

    void potential_init(int num_vertices) {
        memset(potential, 0, sizeof(potential));
        for (int iter = 1; iter < num_vertices; ++iter) {
            for (int e = 0; e < edge_count; ++e) {
                if (cap[e]) {
                    potential[ep[e^1]] = min(potential[ep[e^1]], potential[ep[e]] + cost[e]);
                }
            }
        }
    }

    ll update(int source, int sink, ll& total_cost, int num_vertices) {
        memset(visited, 0, sizeof(visited));
        memset(distance, 0x3f, sizeof(distance));
        distance[source] = 0;
        memset(in_queue, -1, sizeof(in_queue));

        int queue_size = 0;
        in_queue[queue[queue_size++] = source] = 0;

        while (queue_size) {
            int u = queue[0];
            in_queue[u] = -1;
            queue[0] = queue[--queue_size];
            if (queue_size) in_queue[queue[0]] = 0;

            for (int i = 0, left_child = 2*i + 1, temp; left_child < queue_size; i = left_child, left_child = 2*i + 1) {
                if (left_child + 1 < queue_size && distance[queue[left_child + 1]] < distance[queue[left_child]]) 
                    left_child++;
                if (distance[queue[left_child]] >= distance[queue[i]]) 
                    break;
                swap(queue[i], queue[left_child]);
                swap(in_queue[queue[i]], in_queue[queue[left_child]]);
            }

            if (visited[u]) continue;
            visited[u] = true;

            for (int e = first[u]; e != -1; e = nxt[e]) {
                int v = ep[e^1];
                if (flo[e] < cap[e] && distance[v] > distance[u] + potential[u] - potential[v] + cost[e]) {
                    distance[v] = distance[u] + potential[u] - potential[v] + cost[e];
                    par[v] = e;
                    if (in_queue[v] < 0) {
                        in_queue[queue[queue_size] = v] = queue_size;
                        queue_size++;
                    }
                    for (int index = in_queue[v], parent = (index - 1)/2, temp; 
                         index > 0 && distance[queue[index]] < distance[queue[parent]]; 
                         index = parent, parent = (index - 1)/2) {
                        swap(queue[index], queue[parent]);
                        swap(in_queue[queue[index]], in_queue[queue[parent]]);
                    }
                }
            }
        }

        if (distance[sink] >= INF) return 0;

        ll augment = INF;
        for (int e, node = sink; node != source; node = ep[e]) {
            e = par[node];
            augment = min(augment, cap[e] - flo[e]);
        }

        for (int e, node = sink; node != source; node = ep[e]) {
            e = par[node];
            flo[e] += augment;
            flo[e^1] -= augment;
            total_cost += augment * cost[e];
        }

        for (int i = 0; i < num_vertices; ++i) {
            potential[i] = min((ll)INF, distance[i] + potential[i]);
        }

        return augment;
    }

private:
    int queue[MAX_NODES], in_queue[MAX_NODES];
    bool visited[MAX_NODES];
    ll potential[MAX_NODES], distance[MAX_NODES];
};

MinCostFlow mcf;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr); cout.tie(nullptr);
    cout << fixed << setprecision(10);

    int n, m, k, c, d;
    cin >> n >> m >> k >> c >> d;

    const int start_node = 0;
    const int end_node = n*TOTAL_TIME + 1;
    mcf.initialize();

    for(int i = 0; i < k; i++) {
        int a;
        cin >> a;
        mcf.add_connection(start_node, a, 1, 0);
    }

    for(int time = 0; time < TOTAL_TIME; time++) {
        mcf.add_connection(1 + time*n, end_node, INF, 0);
        if(time > 0) {
            for(int node = 1; node <= n; node++) {
                mcf.add_connection(node + (time-1)*n, node + time*n, INF, c);
            }
        }
    }

    for(int i = 0; i < m; i++) {
        int a, b;
        cin >> a >> b;
        for(int level = 0; level < MAX_COST_LEVELS; level++) {
            int cost_factor = (level+1)*(level+1) - level*level;
            for(int time = 1; time < TOTAL_TIME; time++) {
                mcf.add_connection(a + (time-1)*n, b + time*n, 1, cost_factor*d + c);
                mcf.add_connection(b + (time-1)*n, a + time*n, 1, cost_factor*d + c);
            }
        }
    }

    mcf.potential_init(MinCostFlow::MAX_NODES);
    ll total_cost = 0;
    ll total_flow = 0;
    while (ll aug = mcf.update(start_node, end_node, total_cost, MinCostFlow::MAX_NODES)) {
        total_flow += aug;
    }

    assert(total_flow == k);
    cout << total_cost << NL;

    return 0;
}
